template<class T>struct IsMarketWireVariant:std::bool_constant<std::is_same_v<T,PublicStaffCompensationBasis>||std::is_same_v<T,PublicMarketLaborChange>||std::is_same_v<T,MarketServiceAssetBasis>||std::is_same_v<T,MarketServiceStaffingBinding>||std::is_same_v<T,MarketServiceConditionBasis>||std::is_same_v<T,MarketServiceChangeCause>> {};
template<std::size_t I=0,class A,class T>Status select_market_wire_variant(A& archive,T& value,std::size_t tag){if constexpr(I<std::variant_size_v<T>){if(tag==I){auto prepared=archive.template prepare_default_values<std::variant_alternative_t<I,T>>();if(!prepared.ok)return prepared;value.template emplace<I>();return archive.status();}return select_market_wire_variant<I+1>(archive,value,tag);}else return archive.reject("UnsupportedMarketWireVariant");}
